describe('circuit breaker', () => {
  it('닿지 않으면 db_unavailable(503) 로 빨리 실패하고, 다음 호출은 시도도 하지 않는다', async () => {
    dropped = 0
    const db = new Database(DROPPING, { connectTimeout: 3, role: 'insight_app' })
    const started = Date.now()
    const first = await failure(db.read((sql) => sql`SELECT 1`))
    expect(first.code).toBe('db_unavailable')
    expect(first.status).toBe(503)
    // Retried as a blip first (dropped connections, three connects an
    // attempt), within the budget.
    expect(dropped).toBeGreaterThan(3)
    expect(Date.now() - started).toBeLessThan(5_000)
    expect(databaseBreaker(DROPPING)).toMatchObject({ open: true, strikes: 1 })

    // Another request in the same isolate builds its own Database: the
    // breaker is shared by address, and this one fails without connecting.
    const tried = dropped
    const again = new Database(DROPPING, { connectTimeout: 3 })
    const t = Date.now()
    const second = await failure(again.tx({ accountId: null, roles: [] }, (sql) => sql`SELECT 1`))
    expect(second.code).toBe('db_unavailable')
    expect(second.retryAfter).toBeGreaterThan(0)
    expect(await again.healthy()).toBe(false)
    expect(dropped).toBe(tried)
    expect(Date.now() - t).toBeLessThan(50)
    await Promise.all([db.close(), again.close()])
  })

  it('끊기기만 해도(거절이 아니라) 다시 시도는 2.5초 안에서 멈춘다', async () => {
    const db = new Database(DROPPING, { connectTimeout: 3 })
    const started = Date.now()
    await failure(db.read((sql) => sql`SELECT 1`))
    expect(Date.now() - started).toBeLessThan(4_000)
    await db.close()
  })

  it('기다림이 끝나면 한 번만 시도하고, 또 실패하면 더 오래 연다', async () => {
    const db = new Database(DROPPING, { connectTimeout: 3 })
    await failure(db.read((sql) => sql`SELECT 1`))
    const opened = Date.now()
    dropped = 0
    const later = vi.spyOn(Date, 'now').mockImplementation(() => opened + 11_000)
    await failure(db.read((sql) => sql`SELECT 1`))
    // One attempt - which the driver makes as up to three connects before it
    // gives up on a server that drops them (PATCHED.md 5) - not four.
    expect(dropped).toBe(3)
    const state = databaseBreaker(DROPPING)
    expect(state.strikes).toBe(2)
    // The second wait is twice the first (10 s → 20 s).
    expect(state.retryAfterSeconds).toBeGreaterThanOrEqual(19)
    later.mockRestore()
    await db.close()
  })

  it('받기만 하고 답하지 않는 DB 도 연결 대기 시간에 끝나고 차단기를 연다', async () => {
    const db = new Database(SILENT, { connectTimeout: 1 })
    const started = Date.now()
    const err = await failure(db.read((sql) => sql`SELECT 1`))
    expect(err.code).toBe('db_unavailable')
    expect(Date.now() - started).toBeLessThan(3_000)
    expect(databaseBreaker(SILENT).open).toBe(true)
    await db.close().catch(() => undefined)
  })

  it('다른 주소의 DB 는 막지 않는다', async () => {
    const db = new Database(NOWHERE, { connectTimeout: 3 })
    await failure(db.read((sql) => sql`SELECT 1`))
    expect(databaseBreaker('postgres://nobody:nothing@127.0.0.1:2/none').open).toBe(false)
    await db.close()
  })
})

