    private readonly env: Env,
  ) {}

  /** All effective values. Secrets are decrypted; do not pass this to a client. */
  async all(): Promise<SettingValues> {
    return (await this.load()).values
  }

  /** One typed value. */
  async get<K extends SettingKey>(key: K): Promise<SettingValues[K]> {
    const values = await this.all()
    return values[key]
  }

  /** Several values at once, avoiding repeated snapshot lookups. */
  async pick<K extends SettingKey>(...keys: K[]): Promise<Pick<SettingValues, K>> {
    const values = await this.all()
    const out = {} as Pick<SettingValues, K>
    for (const key of keys) out[key] = values[key]
    return out
  }

  /** Values safe to serve to any client: secrets replaced by a presence flag. */
  async publicView(): Promise<Record<string, unknown>> {
    const values = await this.all()
    const out: Record<string, unknown> = {}
    for (const key of SETTING_KEYS) {
      const spec = SETTINGS[key]
      out[key] = spec.secret === true ? (values[key] ? '설정됨' : '') : values[key]
