  await db`UPDATE insight_priv.accounts SET mfa_enabled = false, mfa_secret_enc = '', mfa_pending_enc = '', mfa_recovery_enc = '', failed_logins = 0, locked_until = NULL WHERE email_norm = 'owner@yeopjari.bid'`
  const adminLogin = await admin.post('/api/v1/auth/admin/login', { email: 'owner@yeopjari.bid', password: 'dev-owner-password-123' })
