export function AdminRewards(): ReactNode {
  const [status, setStatus] = useState('ready')
  const state = useAsync((signal) => api.get<{ items: RewardRow[]; total: number }>(`/api/v1/admin/rewards?status=${status}`, { signal }), [status])
  const [selected, setSelected] = useState<string[]>([])
  const [revealed, setRevealed] = useState<Record<string, Record<string, string>>>({})
  const [busy, setBusy] = useState(false)
  useEffect(() => setSelected([]), [status])

  const reveal = async (id: string) => {
    try {
      const result = await api.post<{ method: string; details: Record<string, string> }>(`/api/v1/admin/rewards/${id}/reveal`)
      setRevealed((r) => ({ ...r, [id]: result.details }))
    } catch (err) {
      failed(err, '열지 못했어요')
    }
  }
  // The list carries every payout detail in it, opened: confirmed, audited.
  const exportList = async () => {
    const count = selected.length || items.length
    if (!window.confirm(`받을 곳(휴대폰·계좌)이 그대로 담긴 파일 ${count}건을 내려받아요. 감사 기록에 남고, 보낸 뒤에는 파일을 지워 주세요.`)) return
    try {
      await api.download('/api/v1/admin/rewards/export', { ids: selected.length ? selected : undefined }, 'insight-payouts.csv')
    } catch (err) {
      failed(err, '내려받지 못했어요')
    }
  }

  const markPaid = async () => {
    const note = window.prompt('지급 메모 (예: 기프티콘 일괄 발송 10/7)') ?? ''
    setBusy(true)
    try {
      const result = await api.post<{ paid: number }>('/api/v1/admin/rewards/paid', { ids: selected, note })
      notifications.show({ color: 'teal', message: `${result.paid}건을 지급 완료로 바꿨어요. 참여자에게 메일이 가요.` })
      setSelected([])
      await state.reload()
    } catch (err) {
      failed(err, '처리하지 못했어요')
    } finally {
      setBusy(false)
    }
  }
  const items = state.data?.items ?? []
  return (
    <div>
      <PageTitle title="보상 지급" sub="받을 곳은 한 건씩 열어요 (열 때마다 감사 기록이 남아요). 보낸 뒤 골라서 지급 완료로 바꾸면 참여자에게 알림 메일이 가요." />
      <Group justify="space-between" mb="md">
        <SegmentedControl
          value={status}
          onChange={setStatus}
          data={Object.entries(REWARD_STATUS).map(([value, v]) => ({ value, label: v.label }))}
  Errors: lazy(() => import('./routes/Admin').then((m) => ({ default: m.AdminErrors }))),
}

